INSERT INTO public.missions (id, stage, title, mission_code, description, unlock_condition, is_active) VALUES
    ('86157cba-318c-3d6c-ab8a-580b1323ff7c', 1, $aimong$우리 주변의 AI 찾기$aimong$, $aimong$S0101$aimong$, $aimong$번역 앱, 추천 영상, 음성 인식, 카메라 앱, 스팸 메일처럼 생활 속 AI 사례를 기능 중심으로 찾아봅니다.$aimong$, NULL, TRUE),
    ('47a13864-b7fc-3a8c-ac89-27ae8f5366a7', 1, $aimong$AI와 일반 프로그램 구분하기$aimong$, $aimong$S0102$aimong$, $aimong$계산기처럼 정해진 규칙을 실행하는 도구와 데이터를 보고 판단하는 AI를 생활 사례로 구분합니다.$aimong$, NULL, TRUE),
    ('2e1fdc1a-ff3e-3a9f-a478-7b090d12e5ae', 1, $aimong$AI는 데이터를 보고 배워요$aimong$, $aimong$S0103$aimong$, $aimong$AI가 사진, 글, 소리 같은 데이터를 활용하며 데이터 품질과 다양성이 결과에 영향을 준다는 점을 이해합니다.$aimong$, NULL, TRUE),
    ('c95f477c-ba0b-3613-a0a3-59c6fbb375ce', 1, $aimong$사진·소리·글을 알아보는 AI$aimong$, $aimong$S0104$aimong$, $aimong$딥러닝 구조 암기보다 사진, 소리, 글을 인식하는 AI의 생활 사례와 한계를 알아봅니다.$aimong$, NULL, TRUE),
    ('1c16001f-ca97-3b9d-a3b3-bed7f2661350', 1, $aimong$AI도 틀릴 수 있어요$aimong$, $aimong$S0105$aimong$, $aimong$AI가 자신 있게 말해도 틀릴 수 있음을 알고 다른 자료와 다시 확인하는 습관을 기릅니다.$aimong$, NULL, TRUE),
    ('2d1960e8-985d-3402-b123-986565bfa3e9', 2, $aimong$AI에게 도움 요청하기$aimong$, $aimong$S0201$aimong$, $aimong$프롬프트 세부 기술보다 목적, 대상, 원하는 형식을 쉬운 말로 알려 주는 기본 사용법을 연습합니다.$aimong$, NULL, TRUE),
    ('9aba288d-c43f-3cbb-8ebb-622812c2a9a0', 2, $aimong$AI 답을 더 알맞게 고치기$aimong$, $aimong$S0202$aimong$, $aimong$AI 답이 목적에 맞지 않을 때 조건을 더하거나 쉬운 말로 다시 요청하고 필요한 부분을 고쳐 봅니다.$aimong$, NULL, TRUE),
    ('46eb38b5-04d9-3ddc-ba12-aa3281d388b7', 2, $aimong$개인정보는 넣지 않기$aimong$, $aimong$S0203$aimong$, $aimong$이름, 주소, 전화번호, 학교, 얼굴, 목소리, 위치 정보처럼 식별될 수 있는 정보를 AI 도구에 넣지 않는 방법을 익힙니다.$aimong$, NULL, TRUE),
    ('33a42ea3-e794-3cf7-86b3-523053e97e0b', 2, $aimong$좋은 데이터와 나쁜 데이터 구분하기$aimong$, $aimong$S0204$aimong$, $aimong$데이터의 정확성, 다양성, 허락, 잘못된 이름표를 살펴 AI 결과가 달라지는 이유를 이해합니다.$aimong$, NULL, TRUE),
    ('bd2cc2f4-b9ed-3512-a772-00548a338ae4', 2, $aimong$AI 결과를 실험하고 고쳐 보기$aimong$, $aimong$S0205$aimong$, $aimong$AI 도구의 결과를 관찰하고 틀린 까닭을 찾아 자료를 보완하거나 다시 확인합니다.$aimong$, NULL, TRUE),
    ('ce49ced9-5114-3824-bcaa-be7b102a5465', 2, $aimong$AI 도움을 내 말로 정리하기$aimong$, $aimong$S0206$aimong$, $aimong$AI가 준 힌트와 예시를 그대로 베끼지 않고 내 표현으로 바꾸며 저작권과 책임을 생각합니다.$aimong$, NULL, TRUE),
    ('e1f12cc1-ab3c-3e16-97d9-1d584890919b', 3, $aimong$AI 답 다시 확인하기$aimong$, $aimong$S0301$aimong$, $aimong$AI 답의 핵심 주장, 날짜, 공식 자료 여부를 확인하고 한 가지 답만 믿지 않는 태도를 기릅니다.$aimong$, NULL, TRUE),
    ('18e08973-00ce-3f59-9362-b05ad1eb2ca3', 3, $aimong$출처와 근거 비교하기$aimong$, $aimong$S0302$aimong$, $aimong$누가, 언제, 어디에, 어떤 근거로 썼는지 살피며 여러 자료를 비교해 믿을 만한 정보를 고릅니다.$aimong$, NULL, TRUE),
    ('ca965f02-d5f7-36c0-960c-f463e53951ff', 3, $aimong$데이터 편향 찾아보기$aimong$, $aimong$S0303$aimong$, $aimong$한쪽 자료만 많거나 특정 집단이 빠진 데이터가 AI 결과를 치우치게 만들 수 있음을 이해합니다.$aimong$, NULL, TRUE),
    ('2e51ec66-f05d-37fe-a76a-2fd8fe62662e', 3, $aimong$AI의 좋은 점과 걱정되는 점$aimong$, $aimong$S0304$aimong$, $aimong$AI의 편리함과 함께 개인정보, 감시, 차별, 책임 문제를 균형 있게 살펴봅니다.$aimong$, NULL, TRUE),
    ('5f01b2ce-caf2-3045-8aac-59f35fa5bc55', 3, $aimong$생활 속 공정한 AI 사용$aimong$, $aimong$S0305$aimong$, $aimong$자율주행 생명 선택 같은 무거운 딜레마보다 학교와 생활 속 추천, 평가, 분류 상황에서 공정성을 판단합니다.$aimong$, NULL, TRUE)
